<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require_once dirname(__DIR__).'/app/Auth/SessionUser.php';require_once dirname(__DIR__).'/app/UI/Workspace.php';require_once dirname(__DIR__).'/app/Contacts/Book.php';
use TNL\Contacts\Book;
header('Cache-Control: no-store');header("Content-Security-Policy: default-src 'self'; style-src 'self'; frame-src 'self'; img-src 'self' data: https:; form-action 'self'; base-uri 'none'; frame-ancestors 'self'");$db=tnl_db();$who=\TNL\Auth\SessionUser::require($db);Book::init($db);$error='';$notice='';$edit=null;$selected=null;$query=trim((string)($_GET['q']??''));$page=max(1,(int)($_GET['page']??1));
if($_SERVER['REQUEST_METHOD']==='POST'){tnl_check_csrf();try{$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);if($action==='save'){$id=Book::save($db,$who,$id,$_POST);header('Location: contacts.php?id='.$id.'&saved=1');exit;}elseif($action==='request'){Book::request($db,$who,$id);header('Location: contacts.php?id='.$id.'&requested=1');exit;}elseif($action==='decide'){Book::decide($db,$who,$id,(string)($_POST['principal']??''),(string)($_POST['decision']??''));header('Location: contacts.php?id='.$id.'&saved=1');exit;}elseif($action==='import'){$upload=$_FILES['csv']??[];if(($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||($upload['size']??0)>1048576||!is_uploaded_file($upload['tmp_name']??''))throw new InvalidArgumentException('Selecciona un CSV de hasta 1 MB.');$count=Book::importCsv($db,$who,file_get_contents($upload['tmp_name']),isset($_POST['private']));$notice=$count.' contactos importados.';}elseif($action==='export'){$csv=Book::exportCsv($db,$who);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="contactos-'.gmdate('Y-m-d').'.csv"');header('X-Content-Type-Options: nosniff');echo $csv;exit;}else throw new InvalidArgumentException('Acción no disponible.');}catch(Throwable $e){if($e instanceof InvalidArgumentException)$error=$e->getMessage();else $error='No se pudo completar la operación.';}}
if(isset($_GET['saved']))$notice='Contacto y permisos guardados.';if(isset($_GET['requested']))$notice='Solicitud enviada al propietario del contacto.';
try{if(isset($_GET['edit']))$edit=Book::owned($db,$who,(int)$_GET['edit']);if(isset($_GET['id']))$selected=Book::read($db,$who,(int)$_GET['id']);$listing=Book::search($db,$who,$query,$page);$requests=Book::requests($db,$who);Book::seen($db,$who);}catch(InvalidArgumentException $e){$error=$e->getMessage();$listing=['rows'=>[],'more'=>false];$requests=[];}
function contact_fields(array $c): void {foreach(['first_name'=>'Nombre','last_name'=>'Apellido','company'=>'Empresa','job_title'=>'Cargo','email'=>'Correo electrónico','phone'=>'Teléfono (opcional)'] as $key=>$label)echo '<label>'.$label.'<input name="'.$key.'" '.($key==='phone'?'':'required').' type="'.($key==='email'?'email':($key==='phone'?'tel':'text')).'" maxlength="'.(['email'=>254,'phone'=>60,'company'=>180,'job_title'=>180][$key]??100).'" value="'.tnl_escape((string)($c[$key]??'')).'"></label>';}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Libreta de direcciones · TNL Mail</title><link rel="stylesheet" href="assets/app.css?v=0.13.0"><script src="assets/workspace.js?v=0.13.0" defer></script></head><body><div class="layout"><?php \TNL\UI\Workspace::sidebar($who['role'],'contacts',$who['name']);?><main class="main"><header class="page-header"><div><span class="eyebrow">TU EQUIPO</span><h1>Libreta de direcciones</h1><p>Contactos compartidos. Los datos privados requieren autorización de su propietario.</p></div><a class="button" href="contacts.php?new=1">Añadir contacto</a></header><?php if($error):?><p class="error" role="alert"><?=tnl_escape($error)?></p><?php endif;?><?php if($notice):?><p class="notice" role="status"><?=tnl_escape($notice)?></p><?php endif;?>
<form method="get" class="contact-search"><label class="sr-only" for="contact-query">Buscar contactos</label><input id="contact-query" name="q" value="<?=tnl_escape($query)?>" placeholder="Nombre, apellido, empresa, cargo o correo autorizado" maxlength="200"><button>Buscar</button></form>
<?php if(isset($_GET['new'])||$edit):?><section class="panel"><h2><?=$edit?'Editar contacto':'Añadir contacto'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="contact-form-grid"><?php contact_fields($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='save'?$_POST:($edit??[]));?></div><label class="inline-check"><input type="checkbox" name="private" <?=($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='save'?isset($_POST['private']):!empty($edit['private']))?'checked':''?>> Privado: ocultar correo y teléfono a quienes no tengan permiso</label><p class="content-note">Nombre, apellido, empresa y cargo son visibles en la libreta. Solo tú administras este contacto y sus permisos.</p><button name="action" value="save">Guardar contacto</button></form></section><?php endif;?>
<?php if($selected):?><article class="panel contact-detail" data-live-region="contact-detail"><span class="badge"><?=$selected['private']?'Privado':'Público para el equipo'?></span><h2><?=tnl_escape($selected['first_name'].' '.$selected['last_name'])?></h2><p><?=tnl_escape($selected['company'].' · '.$selected['job_title'])?></p><?php if($selected['can_read']):?><p><a href="<?=tnl_escape(tnl_url('external.php?view=compose&to='.rawurlencode($selected['email'])))?>"><?=tnl_escape($selected['email'])?></a><?php if($selected['phone']):?> · <?=tnl_escape($selected['phone'])?><?php endif;?></p><?php else:?><p>Correo y teléfono protegidos por <?=tnl_escape($selected['owner_name'])?>.</p><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="id" value="<?=(int)$selected['id']?>"><button name="action" value="request" <?=$selected['access_status']==='pending'?'disabled':''?>><?=$selected['access_status']==='pending'?'Solicitud pendiente':'Solicitar permiso de lectura'?></button></form><?php endif;?><?php if($selected['can_manage']):?><a class="button button-secondary" href="?edit=<?=(int)$selected['id']?>">Editar contacto</a><h3>Quién tiene acceso</h3><p class="content-note">Puedes aprobar solicitudes, conceder acceso y revocarlo. El propietario siempre conserva acceso.</p><?php foreach(Book::permissions($db,$who,(int)$selected['id']) as $access):?><form method="post" class="permission-row"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="id" value="<?=(int)$selected['id']?>"><input type="hidden" name="principal" value="<?=tnl_escape($access['principal'])?>"><input type="hidden" name="action" value="decide"><span><?=tnl_escape($access['requester_name'])?> · <?=tnl_escape(['pending'=>'Pendiente','granted'=>'Con acceso','denied'=>'Denegado','revoked'=>'Revocado'][$access['status']]??$access['status'])?></span><?php if($access['status']==='granted'):?><button name="decision" value="revoked" class="button-secondary">Revocar acceso</button><?php else:?><button name="decision" value="granted">Permitir lectura</button><?php if($access['status']==='pending'):?><button name="decision" value="denied" class="button-secondary">Denegar</button><?php endif;?><?php endif;?></form><?php endforeach;?><form method="post" class="permission-row"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="id" value="<?=(int)$selected['id']?>"><input type="hidden" name="action" value="decide"><input type="hidden" name="decision" value="granted"><label>Dar acceso a<select name="principal" required><?php foreach(Book::people($db) as $person)if($person['principal']!==$who['principal']):?><option value="<?=tnl_escape($person['principal'])?>"><?=tnl_escape($person['name'])?></option><?php endif;?></select></label><button>Conceder permiso</button></form><?php endif;?></article><?php endif;?>
<section class="panel" data-live-region="contact-requests"><h2>Solicitudes y permisos</h2><?php if(!$requests):?><p class="muted">No hay solicitudes ni decisiones para tu cuenta.</p><?php endif;?><?php foreach($requests as $r):?><div class="permission-row"><span><?=tnl_escape($r['first_name'].' '.$r['last_name'].' · '.$r['company'])?> · <?=tnl_escape($r['owner']===$who['principal']?$r['requester_name'].' solicita lectura':(['pending'=>'Solicitud pendiente','granted'=>'Lectura permitida','denied'=>'Solicitud denegada','revoked'=>'Acceso revocado'][$r['status']]??$r['status']))?></span><a href="?id=<?=(int)$r['contact_id']?>">Revisar</a></div><?php endforeach;?></section>
<section class="contact-grid" data-live-region="contact-list"><?php foreach($listing['rows'] as $c):?><article class="panel contact-card"><span class="badge"><?=$c['private']?($c['can_read']?'Privado · con acceso':'Privado · bloqueado'):'Público'?></span><h2><a href="?id=<?=(int)$c['id']?>"><?=tnl_escape($c['first_name'].' '.$c['last_name'])?></a></h2><p><?=tnl_escape($c['company'])?><br><small><?=tnl_escape($c['job_title'])?></small></p><?php if($c['can_read']):?><p><?=tnl_escape($c['email'])?><?php if($c['phone']):?><br><?=tnl_escape($c['phone'])?><?php endif;?></p><?php else:?><p class="muted">Correo y teléfono protegidos.</p><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><button name="action" value="request" <?=$c['access_status']==='pending'?'disabled':''?>><?=$c['access_status']==='pending'?'Solicitud pendiente':'Solicitar lectura'?></button></form><?php endif;?><?php if($c['can_manage']):?><a href="?id=<?=(int)$c['id']?>">Administrar acceso</a><?php endif;?></article><?php endforeach;?></section><?php if(!$listing['rows']):?><p class="empty-state">No se encontraron contactos.</p><?php endif;?><nav class="pagination"><?php if($page>1):?><a href="?q=<?=rawurlencode($query)?>&amp;page=<?=$page-1?>">Anterior</a><?php endif;?><span>Página <?=$page?></span><?php if($listing['more']):?><a href="?q=<?=rawurlencode($query)?>&amp;page=<?=$page+1?>">Siguiente</a><?php endif;?></nav>
<details class="panel"><summary>Importar contactos CSV</summary><p>UTF-8, hasta 500 contactos y 1 MB. Columnas: Nombre, Apellido, Empresa, Cargo, Correo; Telefono y Privado son opcionales. Los contactos importados quedan a tu nombre.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><label>Archivo CSV<input type="file" name="csv" accept=".csv,text/csv" required></label><label class="inline-check"><input type="checkbox" name="private"> Importar todos como privados</label><button name="action" value="import">Importar contactos</button></form></details>
<?php if($who['role']==='admin'):?><section class="panel"><h2>Exportar contactos</h2><p>Solo administración puede exportar. El archivo incluye contactos públicos y privados para los que tu cuenta tiene permiso; los privados bloqueados se excluyen.</p><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><button name="action" value="export">Descargar CSV</button></form></section><?php endif;?></main></div></body></html>
